BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."StudentPaymentGatewayConfiguration" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "GatewayCode" varchar(40) NOT NULL,
    "Environment" smallint NOT NULL,
    "ClientId" varchar(250) NOT NULL,
    "ProtectedClientSecret" varchar(4096) NOT NULL,
    "ProtectedWebhookSecret" varchar(4096) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT false,
    "Version" integer NOT NULL DEFAULT 1,
    "CreatedById" bigint NOT NULL,
    "CreatedDateTime" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp without time zone,
    CONSTRAINT "FK_StudentPaymentGatewayConfiguration_Institution"
        FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentPaymentGatewayConfiguration_Environment" CHECK ("Environment" IN (1, 2)),
    CONSTRAINT "CK_StudentPaymentGatewayConfiguration_Version" CHECK ("Version" > 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentPaymentGatewayConfiguration_Institution_Gateway"
    ON skolenza."StudentPaymentGatewayConfiguration" ("InstitutionId", "GatewayCode");

COMMIT;
